    v=g[i][j]
    if ax==1:  # vertical gap: check left and right continuations
        l=(j>0 and g[i][j-1]==v and g[i][j-2]==v); r=(j<w-1 and g[i][j+1]==v and g[i][j+2]==v)
        return not l or not r   # endpoint means at least one side terminates after 1 more
    else:
        u=(i>0 and g[i-1][j]==v and g[i-2][j]==v); d=(i<h-1 and g[i+1][j]==v and g[i+2][j]==v)
        return not u or not d

