def comps(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=max(cnt,key=cnt.get)
    seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; pid=set()
                while q:
