def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r); bg=max(cnt,key=cnt.get)
    nb=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg]
    r0=min(i for i,j in nb); r1=max(i for i,j in nb)
    c0=min(j for i,j in nb); c1=max(j for i,j in nb)
    out=[row[:] for row in g]
    # bbox perimeter -> 2
    for i in (r0,r1):
        for j in range(c0,c1+1): out[i][j]=2
    for j in (c0,c1):
        for i in range(r0,r1+1): out[i][j]=2
    # fill gaps length<=2 with equal flanks
    for i in range(H):
        for j in range(c0,c1+1):
            if g[i][j]==bg: continue
            L=R=D=None
            for k in range(c0,j-1,-1):
                if g[i][k]!=bg: L=k; break
            for k in range(j+1,c1+1):
                if g[i][k]!=bg: R=k; break
            if R is not None and L is not None and abs(R-L-1)<=2:
                for k in range(L+1,R): out[i][k]=2
            # vertical
            for k in range(r0,i-1,-1):
                if g[k][j]!=bg: U=k; break
            for k in range(i+1,r1+1):
                if g[k][j]!=bg: D=k; break
            if D is not None and U is not None and abs(D-U-1)<=2:
                for k in range(U+1,D): out[k][j]=2
    return out

