def f(A):
    out=[r[:] for r in A]
    H,W=len(A),len(A[0])
    cnt=Counter(x for r in A for x in r); bg=max(cnt,key=cnt.get)
    # find each connected component of non-bg; bbox
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if A[i][j]!=bg and not seen[i][j]:
                col=A[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and not seen[x][y] and A[x][y]==col:
                            seen[x][y]=True; q.append((x,y))
                comps.append((col,cells))
    for col,cells in comps:
        rows_=[p[0] for p in cells]; cols_=[p[1] for p in cells]
        for (i,j) in cells: continue
        for i in range(min(rows_),max(rows_)+1):
            for j in range(min(cols_),max(cols_)+1):
                if A[i][j]==bg:
                    # horiz bracket? both same row neighbors in comp with equal color at nearest edges
                    cL=next((c for c in cols_ if c<j), None)
                    cR=next((c for c in cols_ if c>j), None)
                    rU=next((r for r in rows_ if r<i), None)
                    rD=next((r for r in rows_ if r>i), None)
                    if cL is not None and cR is not None and A[i][cL]==A[i][cR]:
                        out[i][j]=2
                    elif rU is not None and rD is not None and A[rU][j]==A[rD][j]:
                        out[i][j]=2
    return out

