    out=[r[:] for r in A]; changed=set()
    while True:
        added=[]
        for i in range(H):
            for j in range(W):
                if A[i][j]==v: continue
                nb=nbg(A,i,j,v)
                if nb>=2:
                    out[i][j]=2; added.append((i,j)); changed.add((i,j))
        if not added: break
    return out
for n in [3,4,5,6,7]:
    Ai=G[f'Demo pair {n} input']; Ao=G[f'Demo pair {n} output']
    o=f(Ai)
    w=[(i,j,o[i][j],Ao[i][j]) for i in range(len(o)) for j in range(len(o[0])) if o[i][j]!=Ao[i][j]]
    print(n,'match' if not w else f'{len(w)} wrong', w[:12])
